package com.hrflow.controller; import com.hrflow.entity.*;import com.hrflow.repository.*;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.math.*;import java.time.*;import java.util.*; @RestController@RequestMapping("/api/payroll")@RequiredArgsConstructor public class PayrollController{final PayrollRepository r;final EmployeeRepository e;@GetMapping public List<Payroll> all(@RequestParam(required=false)Long employeeId){return employeeId==null?r.findAll():r.findByEmployeeIdOrderByPayMonthDesc(employeeId);}@PostMapping("/generate")@PreAuthorize("hasAnyRole('ADMIN','HR')")public Payroll generate(@RequestParam Long employeeId,@RequestParam String month){Employee emp=e.findById(employeeId).orElseThrow();Payroll p=r.findByEmployeeIdAndPayMonth(employeeId,month).orElseGet(Payroll::new);p.setEmployeeId(employeeId);p.setPayMonth(month);p.setBasic(emp.getBasicSalary());p.setAllowances(emp.getAllowances());p.setDeductions(emp.getDeductions());p.setBonus(BigDecimal.ZERO);p.setOvertime(BigDecimal.ZERO);p.setTax(BigDecimal.ZERO);p.setGross(p.getBasic().add(p.getAllowances()).add(p.getBonus()).add(p.getOvertime()));p.setNet(p.getGross().subtract(p.getDeductions()).subtract(p.getTax()));p.setStatus(PayrollStatus.PROCESSED);return r.save(p);}@PutMapping("/{id}/process")@PreAuthorize("hasAnyRole('ADMIN','HR')")public Payroll process(@PathVariable Long id){Payroll p=r.findById(id).orElseThrow();p.setStatus(PayrollStatus.PROCESSED);return r.save(p);}@PutMapping("/{id}/mark-paid")@PreAuthorize("hasAnyRole('ADMIN','HR')")public Payroll paid(@PathVariable Long id){Payroll p=r.findById(id).orElseThrow();p.setStatus(PayrollStatus.PAID);p.setPaidAt(Instant.now());return r.save(p);}}
